(window.LADDER_CARDS=window.LADDER_CARDS||{})["23·phys"]=[{"q": "Light crosses from air into water. What stays the same on both sides?", "a": "n sin θ, with θ from the upright", "w": ["n θ, with θ from the upright", "sin θ / n, with θ from the upright", "n cos θ, with θ from the surface"], "why": "The kept-sine technique: least time keeps the run over the length, over the speed."}, {"q": "n = c/v for a clear stuff. What does n count?", "a": "how many times slower light runs in it than in empty space", "w": ["how many times faster light runs in it than in air", "how sharply its surface bends", "the slant at which light enters it"], "why": "n is the speed in empty space over the speed in the stuff."}, {"q": "A flat glass plate lies on water. Light enters the glass from air at 60° from the upright. What sets its slant in the water?", "a": "only the air and the water: n sin θ is kept at both faces", "w": ["only the glass: the last face it crossed", "the thickness of the plate", "the glass and the water, but not the air"], "why": "1 × sin 60° = 1.52 sin θ_glass = 1.33 sin θ_water."}, {"q": "x_F = R/(√(n² − s²) − √(1 − s²)) for a ray at height y = sR. What is this?", "a": "where the ray crosses the axis, past the centre", "w": ["where every ray crosses the axis, past the front", "the height at which the ray leaves the glass", "the slant of the ray inside the glass"], "why": "The crossing technique: it depends on s, so each height has its own crossing."}, {"q": "Does a round glass surface bring every ray parallel to its axis to one point?", "a": "no: rays farther out cross a little short", "w": ["yes, at nR/(n − 1) behind the front", "yes, if the glass is thick enough", "no: rays farther out cross a little long"], "why": "The crossing technique gives a crossing that falls as the height grows."}, {"q": "nR/(n − 1) behind a round glass front. What is it?", "a": "where rays near the axis gather", "w": ["where the edge rays cross", "the radius of the front", "the length the light runs inside the glass"], "why": "The falling-short technique: near the axis the crossing heads to R/(n − 1) past the centre."}, {"q": "A ray at height y falls short of the focus by about y²/(2n(n − 1)R). The opening is halved. What happens to the shortfall?", "a": "it shrinks to a quarter", "w": ["it halves", "it doubles", "it stays the same"], "why": "The shortfall grows as the square of the height."}, {"q": "sin θ ≈ θ, so θ₂ = θ₁/n. Why does this make a lens work?", "a": "the bend is in proportion to the height, so all rays meet at one spot", "w": ["the light runs faster near the axis", "the glass is thinner at its edge", "every slant is then 0"], "why": "Dip θ₁(n − 1)/n and run y over the dip give nR/(n − 1) for every y."}, {"q": "sin 10° ≈ 10. What is wrong?", "a": "the small-slant reading needs radians: 10° is about 0.1745", "w": ["nothing, 10 is a small slant", "sin 10° is 0", "the reading needs degrees, not radians"], "why": "sin θ ≈ θ holds with θ in radians; a sine is never above 1."}, {"q": "A star’s full yearly swing is 0.10″. What is its parallax p?", "a": "0.05″", "w": ["0.10″", "0.20″", "0.025″"], "why": "The swing is across two AU; p is the slant of one AU, half the swing."}, {"q": "A star has parallax 0.5″. How far away is it?", "a": "2 parsecs", "w": ["0.5 parsecs", "5 parsecs", "4 parsecs"], "why": "The parallax technique: d ≈ 1 AU/p, and p = 1″ gives one parsec."}, {"q": "d = 1 AU/tan p is read as 1 AU/p. By what share at most is that too far?", "a": "less than p²/2", "w": ["less than p", "about p/2", "less than 2p²"], "why": "cos p ≤ p/tan p ≤ 1, and cos p ≥ 1 − p²/2."}];
